def solve_tiling(rows, cols, shapes_list):
    grid = [[0 for _ in range(cols)] for _ in range(rows)]

    def backtrack():
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 0:
                    for shape in shapes_list:
                        # Try to place the shape such that its first cell (relative 0,0) is at (r,c)
                        # Wait, the shape's "first" cell is not necessarily (0,0) in the shape's list.
                        # Let's normalize each shape so that its first cell (in row-major order) is (0,0).
                        possible = True
                        cells_to_fill = []
                        for dr, dc in shape:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 0:
                                cells_to_fill.append((nr, nc))
                            else:
                                possible = False
                                break

                        if possible:
                            for nr, nc in cells_to_fill:
                                grid[nr][nc] = 1
                            if backtrack():
                                return True
                            for nr, nc in cells_to_fill:
                                grid[nr][nc] = 0
                    return False
        return True

    return backtrack()

